+static qint64 parentPidInSameCGroup(qint64 pid)
+{
+    auto readProcFile = [](qint64 pid, const char *name) {
+        QFile file(u"/proc/%1/%2"_s.arg(pid).arg(QLatin1String(name)));
+        return file.open(QIODevice::ReadOnly) ? file.readAll() : QByteArray();
+    };
+
+    // The command name in /proc/<pid>/stat is in parentheses and may contain spaces.
+    const QByteArray stat = readProcFile(pid, "stat");
+    const QList<QByteArray> fields = stat.mid(stat.lastIndexOf(')') + 2).split(' ');
+    if (fields.size() < 2) {
+        return -1;
+    }
+    const qint64 parentPid = fields.at(1).toLongLong();
+    const QByteArray cgroup = readProcFile(pid, "cgroup");
+    if (parentPid <= 1 || cgroup.isEmpty() || cgroup != readProcFile(parentPid, "cgroup")) {
+        return -1;
+    }
+    return parentPid;
+}
