+void AudioShortcutsService::muteActiveApplication()
+{
+    QDBusMessage message = QDBusMessage::createMethodCall(u"org.kde.KWin"_s, u"/KWin"_s, u"org.kde.KWin"_s, u"getActiveWindowInfo"_s);
+    auto *watcher = new QDBusPendingCallWatcher(QDBusConnection::sessionBus().asyncCall(message), this);
+    connect(watcher, &QDBusPendingCallWatcher::finished, this, [this, watcher] {
+        watcher->deleteLater();
+        QDBusPendingReply<QVariantMap> reply = *watcher;
+        if (reply.isError() || reply.value().isEmpty()) {
+            return;
+        }
+        const qint64 pid = reply.value().value(u"pid"_s).toLongLong();
+        const QString appId = reply.value().value(u"desktopFile"_s).toString();
+
+        // Match streams like the Task Manager does: by portal app id first, then by PID, then by parent PID
+        QList<PulseAudioQt::SinkInput *> streams;
+        const auto sinkInputs = PulseAudioQt::Context::instance()->sinkInputs();
+        auto findStreams = [&](auto matches) {
+            for (auto *stream : sinkInputs) {
+                if (!stream->isVirtualStream() && stream->client() && matches(stream->client()->properties())) {
+                    streams.append(stream);
+                }
+            }
+        };
+        if (!appId.isEmpty()) {
+            findStreams([&](const QVariantMap &properties) {
+                return properties.value(u"pipewire.access.portal.app_id"_s).toString() == appId;
+            });
+        }
+        if (streams.isEmpty() && pid > 0) {
+            findStreams([&](const QVariantMap &properties) {
+                return properties.value(u"application.process.id"_s).toLongLong() == pid
+                    && properties.value(u"pipewire.access.portal.app_id"_s).toString().isEmpty();
+            });
+        }
+        if (streams.isEmpty() && pid > 0) {
+            findStreams([&](const QVariantMap &properties) {
+                return parentPidInSameCGroup(properties.value(u"application.process.id"_s).toLongLong()) == pid;
+            });
+        }
+        if (streams.isEmpty()) {
+            return;
+        }
+
+        const bool mute = !std::all_of(streams.cbegin(), streams.cend(), [](PulseAudioQt::SinkInput *stream) {
+            return stream->isMuted();
+        });
+        for (auto *stream : std::as_const(streams)) {
+            stream->setMuted(mute);
+        }
+
+        if (!m_globalConfig->muteOsd()) {
+            return;
+        }
+        QString appName = streams.constFirst()->client()->properties().value(u"application.name"_s).toString();
+        if (appName.isEmpty()) {
+            appName = reply.value().value(u"caption"_s).toString();
+        }
+        const QString rtl = QGuiApplication::layoutDirection() == Qt::RightToLeft ? u"-rtl"_s : QString();
+        if (mute) {
+            m_osdDBusInterface->showText(u"audio-volume-muted"_s + rtl, i18nc("@info:status %1 is an application name", "%1 muted", appName));
+        } else {
+            m_osdDBusInterface->showText(u"audio-volume-high"_s + rtl, i18nc("@info:status %1 is an application name", "%1 unmuted", appName));
+        }
+    });
+}
